import 'package:drift/drift.dart' hide Column;
import 'package:flutter/material.dart';
import 'package:grocery_pos/core/database/app_database.dart';
import 'package:grocery_pos/core/di/injection.dart';

class ReportsPage extends StatefulWidget{const ReportsPage({super.key});@override State<ReportsPage> createState()=>_ReportsPageState();}
class _ReportsPageState extends State<ReportsPage>{final db=getIt<AppDatabase>();double revenue=0,cost=0,returns=0;int count=0;@override void initState(){super.initState();load();}Future<void>load()async{final now=DateTime.now();final start=DateTime(now.year,now.month,now.day);final ss=await (db.select(db.sales)..where((t)=>t.createdAt.isBiggerOrEqualValue(start))).get();count=ss.length;revenue=ss.fold(0,(s,x)=>s+x.total);for(final sale in ss){final items=await (db.select(db.saleItems)..where((t)=>t.saleId.equals(sale.id))).get();cost+=items.fold(0,(s,x)=>s+(x.costPrice*x.quantity));}final rs=await (db.select(db.returns)..where((t)=>t.createdAt.isBiggerOrEqualValue(start))).get();returns=rs.fold(0,(s,x)=>s+x.total);if(mounted)setState((){});}Widget card(String title,String value,IconData icon)=>Card(child:Padding(padding:const EdgeInsets.all(18),child:Row(children:[Icon(icon,size:34),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title),Text(value,style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold))]))])));@override Widget build(BuildContext context){final net=revenue-returns;final profit=net-cost;return Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('تقرير اليوم',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),const SizedBox(height:12),card('المبيعات','${revenue.toStringAsFixed(2)} د.ل',Icons.trending_up),const SizedBox(height:8),card('المرتجعات','${returns.toStringAsFixed(2)} د.ل',Icons.keyboard_return),const SizedBox(height:8),card('تكلفة البضاعة','${cost.toStringAsFixed(2)} د.ل',Icons.shopping_cart),const SizedBox(height:8),card('الربح التقريبي','${profit.toStringAsFixed(2)} د.ل',Icons.savings_outlined),const SizedBox(height:8),card('عدد الفواتير','$count',Icons.receipt_long)]) );}}
